<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api} from '../api/client'
import {names,date,type Family} from '../types'
interface ProgressData {completed_sessions:number;practice:{family:Family;difficulty:number;independent:number;correct:number;assisted:number;hint_total:number}[];checks:{session_id:string;mode:string;manifest:{version:string;form:string;transfer_type:string|null;prior_releases:number;repeated_form:boolean};correct:number;count:number;released:boolean;created:number}[];calibration:{brier:number|null;count:number};delayed_review:{count:number;correct:number};restored_unverified:number;hint_trend:{week:number;family:Family;difficulty:number;attempts:number;assisted:number;hints:number}[]}
const data=ref<ProgressData|null>(null),error=ref('')
onMounted(async()=>{try{data.value=await api<ProgressData>('/progress')}catch(e){error.value=(e as Error).message}})
</script>
<template><span class="eyebrow">03 / NOTICE WHAT CHANGES</span><h1>Evidence, with context.</h1><p class="lead">A record of practice. A place to ask what transfers.</p><div v-if="error" class="error" role="alert">{{error}}</div><template v-if="data"><section class="progress-overview"><div><span class="eyebrow">COMPLETED SESSIONS</span><strong>{{data.completed_sessions||'—'}}</strong><p>{{data.completed_sessions?'Pages of work, saved.':'No completed sessions yet.'}}</p></div><div><span class="eyebrow">INDEPENDENT PRACTICE</span><strong>{{data.practice.reduce((n,r)=>n+r.independent,0)||'—'}}</strong><p>First answers without hints.</p></div><div><span class="eyebrow">DELAYED RETRIEVAL</span><strong>{{data.delayed_review.count?`${data.delayed_review.correct} / ${data.delayed_review.count}`:'—'}}</strong><p>Unaided reviews after at least a day.</p></div></section>
 <section class="panel"><div class="section-heading"><h2>Practice, by family and level</h2><span>FIRST ATTEMPTS ONLY</span></div><p class="muted">Difficulty changes as you practice. Compare like levels; assisted completions stay separate.</p><div v-if="!data.practice.length" class="empty-inline">No attempts yet. Start a session to begin your record.</div><div v-else><div v-for="r in data.practice" :key="r.family+r.difficulty" class="accuracy-row"><span>{{names[r.family]}} <small>Level {{r.difficulty}}</small></span><div class="accuracy-track" role="img" :aria-label="`${r.correct} correct of ${r.independent} independent attempts`"><span :style="{width:(r.independent?100*r.correct/r.independent:0)+'%'}"></span></div><span>{{r.correct}} / {{r.independent}}</span></div><details open><summary>Source data table</summary><div class="table-scroll"><table><thead><tr><th>Family</th><th>Level</th><th>Independent correct / n</th><th>Assisted attempts</th><th>Hints used</th></tr></thead><tbody><tr v-for="r in data.practice" :key="r.family+r.difficulty"><td>{{names[r.family]}}</td><td>{{r.difficulty}}</td><td>{{r.correct}} / {{r.independent}}</td><td>{{r.assisted}}</td><td>{{r.hint_total}}</td></tr></tbody></table></div></details></div></section>
 <section v-if="data.hint_trend.length" class="panel"><h2>Hint use over time</h2><p class="muted">Weekly windows, separated by family and designed level. Assistance may change with difficulty.</p><div class="table-scroll"><table><thead><tr><th>Window beginning</th><th>Family / level</th><th>Attempts</th><th>Assisted</th><th>Hints</th></tr></thead><tbody><tr v-for="r in data.hint_trend" :key="r.week+r.family+r.difficulty"><td>{{date(r.week)}}</td><td>{{names[r.family]}} / {{r.difficulty}}</td><td>{{r.attempts}}</td><td>{{r.assisted}}</td><td>{{r.hints}}</td></tr></tbody></table></div></section>
 <section class="panel"><h2>Fixed checks & exploratory probes</h2><p class="muted">Checks use fixed designed configurations. Forms are matched by configuration, not psychometrically equated. These results are not IQ or intelligence-gain scores.</p><p v-if="!data.checks.length" class="empty-inline">No completed checks yet. A baseline is optional; practice is always open.</p><div v-for="c in data.checks" :key="c.session_id" class="check-result"><div><span class="eyebrow">{{c.mode==='check'?'UNAIDED CHECK':'EXPLORATORY PRESENTATION PROBE'}} / FORM {{c.manifest.form}}</span><h3>{{c.correct}} correct / {{c.count}} problems</h3><p>{{c.manifest.transfer_type||'Familiar task families, fixed level 2.'}}</p><p class="micro">{{c.manifest.version}} · {{date(c.created)}} · {{c.released?'SOLUTIONS RELEASED':'SOLUTIONS SEALED'}}{{c.manifest.prior_releases?' · PRIOR EXPOSURE RECORDED':''}}{{c.manifest.repeated_form?' · REPEATED FORM':''}}</p></div><RouterLink :to="'/train/'+c.session_id">Open result ↗</RouterLink></div></section>
 <section class="lower-grid"><div class="notebook-note"><span class="eyebrow">CONFIDENCE CALIBRATION</span><h3>{{data.calibration.brier===null?'No confidence samples yet.':data.calibration.brier.toFixed(3)+' Brier score'}}</h3><p>Based on {{data.calibration.count}} optional predictions. Mean squared difference between your confidence and outcome; lower means closer calibration. This measures prediction accuracy, not ability.</p></div><div class="measurement-note"><span class="eyebrow">WHAT THIS CAN TELL US</span><h3>Specific practice. Specific evidence.</h3><p>Practice, delayed retention, and presentation transfer are different outcomes. None alone establishes an increase in general intelligence.</p><RouterLink to="/about">Read the research note ↗</RouterLink></div></section><p v-if="data.restored_unverified" class="notice">{{data.restored_unverified}} restored, unverified records are saved separately and excluded from canonical progress and check results.</p></template></template>
